package cli

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/spf13/cobra"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// commandSurface is everything harnaas accepts, and whether each command
// renders its result as a JSON document.
//
// It is written out here rather than derived from the tree, because a test that
// asked the tree what the tree contains would agree with any tree. Declared, it
// makes adding a command a two-line change — the constructor call in
// NewRootCmd, and a line here — and the second line is the moment somebody
// decides whether the new verb has a machine-readable view. A command whose
// result a CI job or a coding agent would want to read and which answers false
// here is a decision, not an oversight.
//
// Nothing declares --json yet: `init` writes a file and prints a path, and a
// document restating the path it just printed would be a JSON view invented to
// have one. `install` and `lint` arrive with their own changes and their own
// lines here.
var commandSurface = map[string]bool{
	"harnaas":      false,
	"harnaas init": false,
}

// cobraGenerated names the commands cobra adds on its own behalf. They are not
// harnaas's surface — nobody here decides what they accept — so the walk skips
// them rather than the surface map having to list them.
var cobraGenerated = map[string]bool{
	"help":       true,
	"completion": true,
}

// walkCommands visits cmd and every harnaas command beneath it, passing the
// full command path a user would type.
func walkCommands(cmd *cobra.Command, path string, visit func(path string, cmd *cobra.Command)) {
	visit(path, cmd)
	for _, child := range cmd.Commands() {
		if cobraGenerated[child.Name()] {
			continue
		}
		walkCommands(child, path+" "+child.Name(), visit)
	}
}

// TestCommandTreeMatchesTheDeclaredSurface is the wiring guardrail: the tree
// NewRootCmd builds and the surface declared above are the same set, and each
// command's --json availability is the one declared for it.
//
// Comparing the whole map in one assertion rather than looping is deliberate: a
// command added without a line here fails as a diff naming it, and so does a
// command that quietly grew or lost a --json flag.
func TestCommandTreeMatchesTheDeclaredSurface(t *testing.T) {
	t.Parallel()

	got := map[string]bool{}
	walkCommands(NewRootCmd(), "harnaas", func(path string, cmd *cobra.Command) {
		got[path] = cmd.Flags().Lookup(jsonFlagName) != nil
	})

	assert.Equal(t, commandSurface, got,
		"the command tree and the declared surface disagree; update commandSurface when adding a command or a --json view")
}

// TestEveryCommandIsReachableFromTheRoot checks the other half of wiring: a
// command that exists in the tree is one a user can actually run. A command
// constructed and attached under a name cobra resolves to something else, or
// attached with neither a RunE nor subcommands, is unreachable in the only
// sense that matters.
func TestEveryCommandIsReachableFromTheRoot(t *testing.T) {
	t.Parallel()

	for path := range commandSurface {
		t.Run(path, func(t *testing.T) {
			t.Parallel()

			root := NewRootCmd()
			args := strings.Fields(path)[1:] // drop the binary name

			found, remaining, err := root.Find(args)
			require.NoError(t, err)
			assert.Equal(t, path, found.CommandPath(), "%q resolved to a different command", path)
			assert.Empty(t, remaining, "part of %q was not matched as a command", path)
			assert.True(t, found.Runnable() || found.HasSubCommands(),
				"%q can be typed but does nothing: it has neither a RunE nor subcommands", path)
		})
	}
}

// TestNoCommandInheritsAFlag is the rule that gives --json its meaning, checked
// over the real tree rather than over a synthetic child: nothing is inherited,
// so a flag a command accepts is a flag that command honours.
func TestNoCommandInheritsAFlag(t *testing.T) {
	t.Parallel()

	walkCommands(NewRootCmd(), "harnaas", func(path string, cmd *cobra.Command) {
		assert.False(t, cmd.InheritedFlags().HasFlags(),
			"%q inherits flags it did not declare and may not honour:\n%s", path, cmd.InheritedFlags().FlagUsages())
	})
}

// TestJSONResultIsAloneOnStdoutThroughTheWholeCommandPath is the output
// contract observed from outside: a command registers --json with the shared
// helper, reads it back with the shared helper, and renders through the shared
// helper — and the result of all three is a stdout carrying one parseable
// document with every advisory line on stderr.
//
// output_test.go tests the helpers directly; this drives them through cobra's
// own execution, which is the path a user's `harnaas … --json | jq` takes.
func TestJSONResultIsAloneOnStdoutThroughTheWholeCommandPath(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name       string
		args       []string
		wantStdout string
	}{
		{
			name:       "without the flag the result is the human text",
			args:       []string{"renders"},
			wantStdout: "installed 2 assets\n",
		},
		{
			name:       "with the flag the result is the document alone",
			args:       []string{"renders", "--json"},
			wantStdout: "{\n  \"installed\": 2\n}\n",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			var stdout, stderr bytes.Buffer
			root := NewRootCmd()
			addCommand(root, newRenderingCmd(), groupAssets)
			root.SetArgs(tc.args)
			root.SetOut(&stdout)
			root.SetErr(&stderr)

			require.NoError(t, root.Execute())

			assert.Equal(t, tc.wantStdout, stdout.String())
			assert.Equal(t, "Resolving 2 assets…\n", stderr.String(),
				"every advisory line belongs on stderr whether or not --json was requested")
		})
	}

	t.Run("the document parses on its own", func(t *testing.T) {
		t.Parallel()

		var stdout bytes.Buffer
		root := NewRootCmd()
		addCommand(root, newRenderingCmd(), groupAssets)
		root.SetArgs([]string{"renders", "--json"})
		root.SetOut(&stdout)
		root.SetErr(&bytes.Buffer{})

		require.NoError(t, root.Execute())

		var doc map[string]any
		require.NoError(t, json.Unmarshal(stdout.Bytes(), &doc),
			"stdout must parse as a single JSON document, got %q", stdout.String())
		assert.Equal(t, map[string]any{"installed": float64(2)}, doc)
	})
}

// newRenderingCmd is a stand-in for a command with a JSON view, wired the way a
// real one would be: --json registered with addJSONFlag, read with
// jsonRequested, rendered with printJSON, and everything else through advisef.
// It exists because no command in this change has a JSON view yet, and the
// contract has to be guarded before the first one does.
func newRenderingCmd() *cobra.Command {
	cmd := newLeafCmd("renders")
	addJSONFlag(cmd)
	cmd.RunE = func(cmd *cobra.Command, _ []string) error {
		advisef(cmd, "Resolving %d assets…\n", 2)

		if jsonRequested(cmd) {
			return printJSON(cmd, map[string]int{"installed": 2})
		}

		fmt.Fprintf(cmd.OutOrStdout(), "installed %d assets\n", 2)
		return nil
	}
	return cmd
}

package cli

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// The two rules forbidigo encodes, asserted again over the module's own syntax.
//
// A lint rule is silenceable: `//nolint:forbidigo` with a plausible-looking
// reason passes review more easily than it should, and both of these rules fail
// quietly rather than loudly — a command that read the process working
// directory would work perfectly until somebody ran it from a subdirectory, and
// one that used a Print* helper would put its result on the wrong stream and
// only break the pipeline of whoever was parsing it. So the rules are checked
// twice: golangci-lint catches them while the code is being written, and this
// catches a suppression that got past review.
//
// These tests live in the cli package because that is where the rules are
// documented, but they walk the whole module: internal/ and the entrypoint are
// bound by them too.

// forbiddenPrintNames are the method names that write to a stream the caller
// did not choose. The rule is stated for cobra's helpers — they write to
// OutOrStderr, so a command's result would land on stderr — but it is asserted
// against every receiver, because fmt's and log's package-level printers write
// to a process global for the same reason and are just as invisible to a test
// capturing the command's own writers.
var forbiddenPrintNames = map[string]bool{
	"Print":   true,
	"Printf":  true,
	"Println": true,
}

// workingDirectoryReader is the one sanctioned call to os.Getwd, expressed as a
// module-relative path. paths.WithDiscoveredRoot is the abstraction forbidigo's
// message names, so the suppression belongs inside it and nowhere else.
var workingDirectoryReader = filepath.Join("cmd", "harnaas", "cli", "paths", "paths.go")

func TestOnlyTheProjectRootResolverReadsTheWorkingDirectory(t *testing.T) {
	t.Parallel()

	var found []string
	forEachSourceFile(t, func(rel string, file *ast.File) {
		osName, ok := importedAs(file, "os")
		if !ok {
			return
		}
		if callsSelector(file, osName, "Getwd") {
			found = append(found, rel)
		}
	})

	assert.Equal(t, []string{workingDirectoryReader}, found,
		"os.Getwd() breaks when a command runs from a subdirectory; resolve the project root once and read it from the context with paths.ProjectRoot(ctx)")
}

func TestNoSourceWritesThroughAPrintHelper(t *testing.T) {
	t.Parallel()

	var found []string
	forEachSourceFile(t, func(rel string, file *ast.File) {
		ast.Inspect(file, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok || !forbiddenPrintNames[sel.Sel.Name] {
				return true
			}
			receiver, ok := sel.X.(*ast.Ident)
			if !ok {
				return true
			}
			found = append(found, rel+": "+receiver.Name+"."+sel.Sel.Name)
			return true
		})
	})

	assert.Empty(t, found,
		"a Print* helper writes to a stream the caller did not choose; write to the command's own writers with fmt.Fprint*(cmd.OutOrStdout(), …) or advisef")
}

// forEachSourceFile parses every non-test Go file in the module and hands it to
// visit with its module-relative path.
//
// Test files are excluded on purpose: a test may legitimately name anything it
// is asserting about, including the very calls these rules forbid.
func forEachSourceFile(t *testing.T, visit func(rel string, file *ast.File)) {
	t.Helper()

	root := moduleRoot(t)
	fset := token.NewFileSet()

	require.NoError(t, filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			if skipDir(entry.Name()) && path != root {
				return fs.SkipDir
			}
			return nil
		}

		name := entry.Name()
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			return nil
		}

		file, parseErr := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
		if parseErr != nil {
			return parseErr
		}

		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			return relErr
		}
		visit(rel, file)
		return nil
	}))
}

// skipDir reports whether a directory holds nothing this rule applies to:
// dot-directories, test fixtures, and the dependency trees a module may vendor.
// Their contents are somebody else's code, and a rule harnaas states about
// itself is not one it gets to state about them.
func skipDir(name string) bool {
	return strings.HasPrefix(name, ".") || name == "testdata" || name == "vendor" || name == "node_modules"
}

// moduleRoot walks up from the test's own directory to the directory holding
// go.mod, so the walk covers the module however deep the test sits.
func moduleRoot(t *testing.T) string {
	t.Helper()

	dir, err := filepath.Abs(".")
	require.NoError(t, err)

	for {
		if _, statErr := os.Stat(filepath.Join(dir, "go.mod")); statErr == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		require.NotEqual(t, dir, parent, "no go.mod above %s", dir)
		dir = parent
	}
}

// importedAs returns the name a file refers to an import path by, honouring an
// alias and the last path segment otherwise. A file that does not import the
// path cannot call into it, whatever an identifier happens to be spelled.
func importedAs(file *ast.File, importPath string) (string, bool) {
	for _, spec := range file.Imports {
		path, err := strconv.Unquote(spec.Path.Value)
		if err != nil || path != importPath {
			continue
		}
		if spec.Name != nil {
			return spec.Name.Name, spec.Name.Name != "_"
		}
		return path[strings.LastIndex(path, "/")+1:], true
	}
	return "", false
}

// callsSelector reports whether file contains a reference to receiver.name.
func callsSelector(file *ast.File, receiver, name string) bool {
	found := false
	ast.Inspect(file, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != name {
			return true
		}
		if ident, ok := sel.X.(*ast.Ident); ok && ident.Name == receiver {
			found = true
		}
		return true
	})
	return found
}

package cli

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/logging"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
)

// The logging guardrails, checked where the commands are rather than inside the
// logging package: that a run's diagnostics reach the log file and neither of
// the command's streams, and that what reaches the file is the path to a file
// and never what was in it.
//
// Neither test can use t.Parallel, because both point HARNAAS_LOG_FILE at a
// scratch file with t.Setenv and the package logger is process-wide.

// logToScratchFile directs harnaas's log at a file under t.TempDir for the
// duration of one test, and returns the records written to it. No test reads or
// writes the real per-user log.
func logToScratchFile(t *testing.T) func() []map[string]any {
	t.Helper()

	path := filepath.Join(t.TempDir(), "harnaas.log")
	t.Setenv(logging.FileEnvVar, path)

	closeLog := logging.Open()
	t.Cleanup(closeLog)

	return func() []map[string]any {
		// Closing first flushes and releases the file, which Windows requires
		// before it can be read.
		closeLog()

		raw, err := os.ReadFile(path)
		require.NoError(t, err, "harnaas wrote no log file at all")

		var records []map[string]any
		for line := range strings.Lines(strings.TrimSpace(string(raw))) {
			line = strings.TrimSpace(line)
			if line == "" {
				continue
			}
			var record map[string]any
			require.NoError(t, json.Unmarshal([]byte(line), &record), "log line is not JSON: %s", line)
			records = append(records, record)
		}
		return records
	}
}

// TestARunsDiagnosticsReachTheLogFileAndNeitherStream is the whole reason
// harnaas logs to a file: a diagnostic on stdout would corrupt a --json
// document mid-parse, and one on stderr would interleave with the text the user
// is reading. `init` is the command that exists to check it with.
func TestARunsDiagnosticsReachTheLogFileAndNeitherStream(t *testing.T) {
	logged := logToScratchFile(t)

	run := runInitIn(t, scratchProject(t))
	require.NoError(t, run.err)

	records := logged()
	require.NotEmpty(t, records, "the run recorded nothing")

	created := findRecord(t, records, "manifest created")
	assert.Equal(t, run.manifestPath(), created["path"])
	assert.InDelta(t, 1.0, created["harness_count"], 0)

	for name, stream := range map[string]string{"stdout": run.stdout, "stderr": run.stderr} {
		assert.NotContains(t, stream, "manifest created", "a log record reached %s", name)
		assert.NotContains(t, stream, `"level"`, "a log record reached %s", name)
	}
}

// TestALogRecordNamesAFileAndNeverItsContents is the privacy rule as a test.
//
// The files harnaas handles are a team's instructions and rules, which is
// exactly the content nobody expects to find copied into a log they did not
// know existed. So a record may say which file harnaas read and what happened;
// it may not say what was in it.
//
// The sentinel is planted as a field name in the manifest, so the decode
// failure quotes it back — the assertion below that the error message contains
// it is the point of the test, not incidental. That message is a good
// diagnostic and a leak: logging err.Error() would be the natural thing to
// write, and would put the author's own file in the log. What a command records
// instead is the path and the failure's type, which is the shape both call
// sites in this binary already use.
func TestALogRecordNamesAFileAndNeverItsContents(t *testing.T) {
	logged := logToScratchFile(t)

	const sentinel = "the_authors_own_words"

	root := scratchProject(t)
	writeFile(t, root, manifest.FileName, fmt.Sprintf(`{
  "version": 1,
  "harnesses": ["claude-code"],
  %q: true
}
`, sentinel))

	ctx := paths.WithProjectRoot(t.Context(), root)
	path, err := manifest.Path(ctx)
	require.NoError(t, err)

	doc, err := manifest.Load(ctx)
	require.Error(t, err)
	require.Nil(t, doc)
	require.Contains(t, err.Error(), sentinel,
		"the diagnostic quotes the author's own file, which is why the message must never be what is logged")

	logging.Error(ctx, "manifest failed to load",
		slog.String("path", path),
		slog.String("error_type", fmt.Sprintf("%T", err)),
	)

	records := logged()
	failed := findRecord(t, records, "manifest failed to load")
	assert.Equal(t, path, failed["path"], "the path is an identifier and belongs in the log")
	assert.Equal(t, "*manifest.DecodeError", failed["error_type"])

	for _, record := range records {
		for key, value := range record {
			assert.NotContains(t, fmt.Sprint(value), sentinel,
				"the file's own content reached the log under key %q", key)
		}
	}
}

// findRecord returns the one record with the given message.
func findRecord(t *testing.T, records []map[string]any, msg string) map[string]any {
	t.Helper()

	for _, record := range records {
		if record["msg"] == msg {
			return record
		}
	}

	require.FailNowf(t, "no such log record", "no record with msg %q in %v", msg, records)
	return nil
}

